import {steps,catalog,initialConfig,evaluate,connectorTypes,assessPerformance} from './data.js';
import {createScene} from './scene.js';
const $=s=>document.querySelector(s);let current=0,done=new Set(),config={...initialConfig},scene,exploded=false,marks=[],corner=null,photoUrl=null;
try{let saved=JSON.parse(localStorage.getItem('buildacademy-state-v1')||'null');if(saved&&Object.keys(catalog).every(k=>catalog[k].options.some(o=>o.id===saved.config?.[k]))){config={...saved.config};if(Array.isArray(saved.reviewed))done=new Set(saved.reviewed.filter(n=>Number.isInteger(n)&&n>=0&&n<steps.length))}}catch{}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function save(){try{localStorage.setItem('buildacademy-state-v1',JSON.stringify({config,reviewed:[...done]}))}catch{toast('Tu navegador no permite guardar el avance.')}}
function setView(view){if(!['guide','compat','photo'].includes(view))throw new Error('Sección desconocida');document.querySelectorAll('.view').forEach(el=>{el.hidden=el.id!==view;el.classList.toggle('active',el.id===view)});document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-selected',b.dataset.view===view)});}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function renderStep(){const s=steps[current];$('#steps').innerHTML=steps.map((s,i)=>`<button class="step ${i===current?'active':''} ${done.has(i)?'done':''}" data-step="${i}" ${i===current?'aria-current="step"':''}><span class="num">${done.has(i)?'✓':String(i+1).padStart(2,'0')}</span><span class="step-name">${s.short}<small>${s.sub}</small></span></button>`).join('');document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>goStep(Number(b.dataset.step)));renderGuideContext();$('#step-number').textContent=`PASO ${String(current+1).padStart(2,'0')} / ${steps.length}`;$('#step-title').textContent=s.title;$('#step-description').textContent=s.description;$('#step-why').textContent=s.why;$('#step-check').textContent=s.check;$('#part-label').textContent=s.label;$('#complete').innerHTML=done.has(current)?'Revisado <span>✓</span>':'Marcar como revisado <span>✓</span>';$('#complete').classList.toggle('done',done.has(current));$('#complete').setAttribute('aria-pressed',done.has(current));$('#count').textContent=`${done.size} / ${steps.length}`;$('#progress').style.width=`${done.size/steps.length*100}%`;$('#prev').disabled=current===0;$('#next').disabled=current===steps.length-1;}
function goStep(i){if(!Number.isInteger(i)||i<0||i>=steps.length)throw new Error('Paso inválido');current=i;renderStep();scene?.setStep(i)}
$('#prev').onclick=()=>goStep(current-1);$('#next').onclick=()=>goStep(current+1);$('#complete').onclick=()=>{if(done.has(current)){done.delete(current)}else{done.add(current);toast(done.size===steps.length?'¡Recorrido revisado! El montaje real requiere su propia verificación.':'Paso marcado como revisado')}save();renderStep()};$('#reset-progress').onclick=()=>{done.clear();save();goStep(0);toast('Recorrido reiniciado')};$('#replay').onclick=()=>scene?.replay();$('#reset-camera').onclick=()=>scene?.reset();$('#explode').onclick=()=>{exploded=!exploded;scene?.explode(exploded);$('#explode').setAttribute('aria-pressed',exploded);$('#explode').textContent=exploded?'Vista ensamblada':'Vista separada'};
renderStep();try{scene=createScene($('#scene'))}catch(e){$('#scene').innerHTML='<p class="scene-error">No se pudo iniciar el visor 3D. Probá un navegador con WebGL habilitado. Podés seguir consultando los pasos y la compatibilidad.</p>';$('#replay').disabled=true;$('#explode').disabled=true;$('#reset-camera').disabled=true;console.error(e)}
for(const [key,c] of Object.entries(catalog)){let label=document.createElement('label');label.htmlFor=`select-${key}`;label.textContent=c.label;let select=document.createElement('select');select.id=`select-${key}`;select.innerHTML=c.options.map(o=>`<option value="${o.id}">${o.name}</option>`).join('');select.value=config[key];select.onchange=()=>changeConfig({[key]:select.value});$('#selectors').append(label,select)}
function renderResults(){let results=evaluate(config),fails=results.filter(r=>r.status==='fail').length;$('#compat-summary').className=`result-summary ${fails?'bad':''}`;$('#compat-summary').innerHTML=fails?`${fails} ${fails===1?'incompatibilidad detectada':'incompatibilidades detectadas'}<small>Revisá las piezas señaladas antes de continuar.</small>`:'Las 4 comprobaciones básicas coinciden<small>La compatibilidad del equipo completo todavía no está confirmada.</small>';$('#results').innerHTML=results.map(r=>`<div class="result ${r.status}"><span class="result-icon">${r.status==='pass'?'✓':r.status==='fail'?'×':'?'}</span><div><h4>${r.name}</h4><p>${r.detail}</p></div></div>`).join('');renderConfigurationDetails()}
function changeConfig(next){for(const k of Object.keys(next)){if(!catalog[k]||!catalog[k].options.some(o=>o.id===next[k]))throw new Error('Componente inválido')}const changed=Object.keys(next).some(k=>config[k]!==next[k]);config={...config,...next};if(changed&&done.size){done.clear();toast('Configuración actualizada. Revisá los pasos para estas piezas.')}save();for(const k of Object.keys(catalog))$(`#select-${k}`).value=config[k];renderResults();renderStep()}
$('#intel-example').onclick=()=>changeConfig({board:'intel',cpu:'intelcpu',ram:'ddr4',ssd:'nvme',gpu:'rx7600'});$('#usage').onchange=renderPerformance;
$('#bad-example').onclick=()=>changeConfig({board:'am5',cpu:'intelcpu',ram:'ddr4',ssd:'sata'});$('#good-example').onclick=()=>changeConfig(initialConfig);renderResults();
$('#connector-type').innerHTML=connectorTypes.map(t=>`<option>${t}</option>`).join('');
function clearCorner(){corner=null;renderMarks();if(photoUrl)$('#photo-status').textContent='Marcá dos esquinas opuestas para señalar un conector.'}$('#cancel-mark').onclick=clearCorner;document.addEventListener('keydown',e=>{if(e.key==='Escape')clearCorner()});
$('#photo-input').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>15*1024*1024){$('#photo-status').textContent='Elegí un archivo JPG, PNG o WebP de hasta 15 MB.';e.target.value='';return}let url=URL.createObjectURL(f),test=new Image();try{test.src=url;await test.decode();if(test.naturalWidth*test.naturalHeight>40000000)throw new Error('La imagen supera los 40 megapíxeles. Reducí su tamaño.');if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=url;marks=[];corner=null;$('#photo-image').src=url;$('#annotations').setAttribute('viewBox',`0 0 ${test.naturalWidth} ${test.naturalHeight}`);$('#photo-area').hidden=false;$('#photo-status').textContent='Marcá dos esquinas opuestas para señalar un conector.';renderMarks()}catch(err){URL.revokeObjectURL(url);$('#photo-status').textContent=err.message?.includes('megapíxeles')?err.message:'No se pudo leer la imagen. Elegí otro archivo.'}};
$('#annotations').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect(),img=$('#photo-image');let p={x:(e.clientX-r.left)/r.width*img.naturalWidth,y:(e.clientY-r.top)/r.height*img.naturalHeight};if(!corner){corner=p;$('#photo-status').textContent='Ahora marcá la esquina opuesta. Escape para cancelar.';renderMarks();return}let x=Math.min(p.x,corner.x),y=Math.min(p.y,corner.y),w=Math.abs(p.x-corner.x),h=Math.abs(p.y-corner.y);if(w<8||h<8){toast('Elegí una zona un poco más grande.');return}marks.push({type:$('#connector-type').value,x,y,w,h});clearCorner()});
function renderMarks(){const img=$('#photo-image'),stroke=Math.max(2,(img.naturalWidth||1000)/350),font=Math.max(15,(img.naturalWidth||1000)/45);$('#annotations').innerHTML=marks.map((m,i)=>`<g><rect x="${m.x}" y="${m.y}" width="${m.w}" height="${m.h}" fill="#bbef7522" stroke="#a8ed5c" stroke-width="${stroke}"/><text x="${m.x+4}" y="${m.y+font}" font-size="${font}" fill="white" stroke="#172719" stroke-width="${stroke*.6}" paint-order="stroke">${i+1}. ${m.type}</text></g>`).join('')+(corner?`<circle cx="${corner.x}" cy="${corner.y}" r="${stroke*3}" fill="#eaaa5a"/>`:'');$('#annotation-list').innerHTML=marks.length?marks.map((m,i)=>`<div class="annotation-item"><span>${i+1}. ${m.type}<br><small>Marca manual · Sin confianza IA</small></span><button data-delete="${i}" aria-label="Eliminar marca ${i+1}">Eliminar</button></div>`).join(''):'<p class="muted">Todavía no hay marcas.</p>';document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{marks.splice(Number(b.dataset.delete),1);renderMarks()})}renderMarks();
// Optional browser-native agent interface shares the same validated UI actions.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_buildacademy_state',description:'Leer paso actual, avance y reglas de compatibilidad.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({step:current+1,reviewed:[...done].map(n=>n+1),config,results:evaluate(config)})},{name:'navigate_assembly_step',description:'Abrir un paso educativo sin marcarlo como revisado.',inputSchema:{type:'object',properties:{step:{type:'integer',minimum:1,maximum:8}},required:['step'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.step)||input.step<1||input.step>8)throw new Error('Paso inválido');setView('guide');goStep(input.step-1);return{step:current+1,title:steps[current].title}}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}

function renderPerformance(){
 const assessment=assessPerformance(config,$('#usage').value);
 $('#performance-results').innerHTML=`<h3>${assessment.title}</h3><p class="muted">${assessment.detail}</p>`+assessment.items.map(item=>`<div class="performance-item"><h4>${item.title}</h4><p>${item.text}</p></div>`).join('');
}
function renderConfigurationDetails(){
 $('#source-links').innerHTML='<span>Fichas oficiales · Consultadas el 21/09/2026</span>'+['board','cpu','gpu'].map(k=>{const item=catalog[k].options.find(o=>o.id===config[k]);return `<a href="${item.source}" target="_blank" rel="noopener noreferrer">${item.name} ↗</a>`}).join('');
 renderPerformance();
}
function renderGuideContext(){
 const board=catalog.board.options.find(o=>o.id===config.board),cpu=catalog.cpu.options.find(o=>o.id===config.cpu),gpu=catalog.gpu.options.find(o=>o.id===config.gpu);
 const failed=evaluate(config).filter(r=>r.status==='fail');
 $('#build-context').innerHTML=`<div><strong>${board.name}</strong><span>${cpu.name} · ${gpu.name}</span></div><button id="edit-config" class="secondary">Cambiar componentes</button><p>${failed.length?'Hay incompatibilidades: usá la guía solo para explorar.':'Configuración vinculada · Verificación completa pendiente.'} El modelo 3D es genérico, no una réplica de estas piezas.</p>`;
 $('#edit-config').onclick=()=>setView('compat');
 let context=current===1?`${cpu.name}: socket ${cpu.socket}. La placa seleccionada utiliza ${board.socket}.`:current===2?`Esta placa utiliza ${board.memory}. Verificá en el manual las posiciones para tu kit.`:current===3?(config.ssd==='sata'?(board.id==='intel'?'M.2 SATA: usá M2_2; SATA8 quedará deshabilitado.':'El SSD M.2 SATA seleccionado no es compatible con los M.2 de esta placa.'):'El perfil seleccionado es NVMe 2280. Identificá M.2_1 o M.2_2 en el manual.'):current===4?`El kit de montaje del cooler debe admitir ${board.socket}.`:current===5?'Esta motherboard utiliza formato ATX. Comprobá soporte y separadores del gabinete.':current===6?`${gpu.name}: falta seleccionar el modelo del ensamblador para verificar dimensiones y cables.`:current===7?board.power:'Consultá las instrucciones del modelo seleccionado antes del montaje real.';
 let node=$('#step-context');if(!node){node=document.createElement('div');node.id='step-context';node.className='step-context';$('.instruction').insertBefore(node,$('#complete'))}
 node.innerHTML=`<p>${context}</p><a href="${board.manual}" target="_blank" rel="noopener noreferrer">Abrir manual de ${board.name} ↗</a>`;
}
